// Headless Node check that the JS engine reproduces the Python reference
// replay trajectories. Reads data/replays/<scenario>.json (generated by
// `python3 -m cli.vc record`) and compares against data/replays/<scenario>.csv.
'use strict';

const fs = require('fs');
const path = require('path');

global.window = global;
require(path.join(__dirname, '..', 'web', 'js', 'math3d.js'));
require(path.join(__dirname, '..', 'web', 'js', 'terrain.js'));
require(path.join(__dirname, '..', 'web', 'js', 'wheel_ground.js'));
require(path.join(__dirname, '..', 'web', 'js', 'vehicle.js'));
require(path.join(__dirname, '..', 'web', 'js', 'simulation.js'));

function parseCsv(text) {
  const lines = text.trim().split('\n');
  const header = lines[0].split(',');
  return lines.slice(1).map(line => {
    const c = line.split(',');
    const row = {};
    header.forEach((h, i) => { row[h] = Number(c[i]); });
    return row;
  });
}

let failures = 0;
for (const scenario of ['slope', 'bump', 'edge']) {
  const replay = JSON.parse(fs.readFileSync(
    path.join(__dirname, '..', 'data', 'replays', scenario + '.json')));
  const pyRows = parseCsv(fs.readFileSync(
    path.join(__dirname, '..', 'data', 'replays', scenario + '.csv'), 'utf8'));
  const sim = window.Sim.runReplay(replay);
  const js = sim.trajectory;
  const n = Math.min(js.length, pyRows.length);
  let maxPos = 0, maxVel = 0, contactMismatch = 0;
  for (let i = 0; i < n; i++) {
    const a = js[i], b = pyRows[i];
    const dp = Math.hypot(a.position[0] - b.x, a.position[1] - b.y,
                          a.position[2] - b.z);
    const dv = Math.hypot(a.velocity[0] - b.vx, a.velocity[1] - b.vy,
                          a.velocity[2] - b.vz);
    maxPos = Math.max(maxPos, dp);
    maxVel = Math.max(maxVel, dv);
    if (a.contact_count !== b.contacts) contactMismatch++;
  }
  // Tight tolerance: positions within 10 cm over a 20 s chaotic edge
  // manoeuvre and *zero* contact-state mismatches. The residual gap is
  // cross-runtime floating-point ordering (~1e-16/step) amplified by the
  // stiff suspension; slope/bump stay at machine-epsilon agreement.
  const ok = maxPos < 0.1 && contactMismatch === 0 && n === pyRows.length;
  console.log(
    `${scenario.padEnd(6)} steps=${n} maxPosErr=${maxPos.toExponential(2)} ` +
    `maxVelErr=${maxVel.toExponential(2)} contactMismatch=${contactMismatch} ` +
    `${ok ? 'OK' : 'FAIL'}`);
  if (!ok) failures++;
}
process.exit(failures ? 1 : 0);
